export type Entry = { term: string; meaning: string; example: string; note?: string };

/** Words from university and test reading that raise lexical resource in Writing and Speaking. */
export const ACADEMIC_WORDS: Entry[] = [
  { term: "allocate", meaning: "to give a share of something for a particular purpose", example: "The council will allocate more funds to public libraries." },
  { term: "ambiguous", meaning: "having more than one possible meaning", example: "The question was ambiguous, so many candidates misread it." },
  { term: "anticipate", meaning: "to expect something and prepare for it", example: "Planners anticipate a sharp rise in demand for housing." },
  { term: "arbitrary", meaning: "based on chance or a personal whim rather than reason", example: "The age limit seems arbitrary rather than based on evidence." },
  { term: "coherent", meaning: "logical and well organised, easy to follow", example: "A coherent essay moves clearly from one idea to the next." },
  { term: "coincide", meaning: "to happen at the same time", example: "The fall in crime coincided with the opening of youth centres." },
  { term: "comprehensive", meaning: "including all or nearly all aspects", example: "The report gives a comprehensive review of the evidence." },
  { term: "constrain", meaning: "to limit or restrict", example: "Small budgets constrain what rural schools can offer." },
  { term: "controversial", meaning: "causing public disagreement", example: "Animal testing remains a controversial issue." },
  { term: "deteriorate", meaning: "to become worse", example: "Air quality deteriorates when traffic increases." },
  { term: "diminish", meaning: "to become or make smaller or less", example: "The benefits of the drug diminish over time." },
  { term: "discrepancy", meaning: "a difference between things that should be the same", example: "There is a discrepancy between the two sets of figures." },
  { term: "disproportionate", meaning: "too large or too small compared with something else", example: "Poorer families spend a disproportionate share of income on food." },
  { term: "empirical", meaning: "based on observation or experiment, not theory", example: "There is little empirical evidence for the claim." },
  { term: "endorse", meaning: "to publicly support or approve", example: "Several doctors endorsed the new health campaign." },
  { term: "exacerbate", meaning: "to make a problem worse", example: "Building more roads may exacerbate congestion." },
  { term: "feasible", meaning: "possible and practical to do", example: "Free public transport may not be financially feasible." },
  { term: "fluctuate", meaning: "to rise and fall irregularly", example: "Oil prices fluctuated throughout the decade." },
  { term: "fundamental", meaning: "basic and very important", example: "Access to clean water is a fundamental human right." },
  { term: "hypothesis", meaning: "an idea that is tested by research", example: "The study tested the hypothesis that sleep improves memory." },
  { term: "implement", meaning: "to put a plan or decision into action", example: "The school implemented a new reading programme." },
  { term: "incentive", meaning: "something that encourages a person to do something", example: "Tax breaks are an incentive for companies to go green." },
  { term: "inevitable", meaning: "certain to happen and impossible to avoid", example: "Some job losses are inevitable as automation spreads." },
  { term: "infrastructure", meaning: "the basic systems a country needs, such as roads and power", example: "Rural areas need better digital infrastructure." },
  { term: "integral", meaning: "necessary to make something complete", example: "Practical work is integral to science education." },
  { term: "intervene", meaning: "to become involved to change a situation", example: "Governments should intervene when markets fail." },
  { term: "justify", meaning: "to show that something is reasonable", example: "Can the high cost of space research be justified?" },
  { term: "legitimate", meaning: "reasonable and acceptable, or allowed by law", example: "Parents have legitimate concerns about online safety." },
  { term: "mitigate", meaning: "to make something less harmful or serious", example: "Trees can mitigate the effects of urban heat." },
  { term: "notion", meaning: "an idea or belief", example: "The notion that money brings happiness is widely questioned." },
  { term: "objective", meaning: "not influenced by personal feelings", example: "Journalists should give an objective account of events." },
  { term: "paradox", meaning: "a situation with two facts that seem to contradict each other", example: "It is a paradox that we are more connected yet lonelier." },
  { term: "phenomenon", meaning: "something that happens or exists and can be observed", example: "Remote working is a relatively recent phenomenon." },
  { term: "plausible", meaning: "seeming reasonable or likely to be true", example: "The theory offers a plausible explanation for the decline." },
  { term: "predominantly", meaning: "mainly; for the most part", example: "The workforce is predominantly young." },
  { term: "prerequisite", meaning: "something needed before something else can happen", example: "A good night's sleep is a prerequisite for learning." },
  { term: "prevalent", meaning: "common or widespread", example: "Obesity is increasingly prevalent among children." },
  { term: "prohibit", meaning: "to officially forbid", example: "Many cities prohibit smoking in public places." },
  { term: "rationale", meaning: "the reasons behind a decision", example: "The rationale for the tax is to reduce sugar consumption." },
  { term: "reluctant", meaning: "unwilling and hesitant", example: "Many drivers are reluctant to give up their cars." },
  { term: "rigorous", meaning: "very thorough and careful", example: "New medicines undergo rigorous testing." },
  { term: "scrutiny", meaning: "careful and detailed examination", example: "Government spending should be open to public scrutiny." },
  { term: "subsequent", meaning: "coming after something else", example: "Subsequent studies confirmed the original results." },
  { term: "substantial", meaning: "large in amount or importance", example: "There was a substantial increase in online sales." },
  { term: "sustainable", meaning: "able to continue without damaging the environment", example: "Cities need sustainable transport systems." },
  { term: "tendency", meaning: "a likelihood to behave in a particular way", example: "There is a tendency for teenagers to sleep later." },
  { term: "undermine", meaning: "to gradually weaken", example: "Fake news can undermine trust in the media." },
  { term: "unprecedented", meaning: "never having happened before", example: "The city saw an unprecedented rise in tourism." },
  { term: "viable", meaning: "able to work successfully", example: "Electric buses are now a viable alternative to diesel." },
  { term: "widespread", meaning: "happening in many places or among many people", example: "There is widespread support for the new law." },
];

