export const PHRASAL_VERBS: Entry[] = [
  { term: "bring about", meaning: "to cause something to happen", example: "Technology has brought about huge changes in education." },
  { term: "bring up", meaning: "to raise a child; or to mention a topic", example: "I was brought up by my grandparents." },
  { term: "carry out", meaning: "to do or complete a task", example: "Scientists carried out a series of experiments." },
  { term: "come up with", meaning: "to think of an idea or plan", example: "We came up with a solution to the problem." },
  { term: "cut down on", meaning: "to reduce the amount of something", example: "I'm trying to cut down on sugar." },
  { term: "deal with", meaning: "to take action to solve a problem", example: "Governments must deal with rising unemployment." },
  { term: "drop out", meaning: "to leave school or a course before finishing", example: "Some students drop out because of financial pressure." },
  { term: "end up", meaning: "to finally be in a place or situation", example: "We got lost and ended up in the next town." },
  { term: "figure out", meaning: "to understand or solve something", example: "It took me a while to figure out the instructions." },
  { term: "get along with", meaning: "to have a friendly relationship", example: "I get along well with my colleagues." },
  { term: "give up", meaning: "to stop doing something", example: "He gave up smoking last year." },
  { term: "go through", meaning: "to experience something difficult", example: "The country went through a period of recession." },
  { term: "keep up with", meaning: "to stay at the same level or speed as", example: "It's hard to keep up with changes in technology." },
  { term: "look forward to", meaning: "to feel happy about something that will happen", example: "I look forward to hearing from you." },
  { term: "look into", meaning: "to investigate", example: "The council will look into the complaints." },
  { term: "make up for", meaning: "to compensate for something", example: "I worked late to make up for the lost time." },
  { term: "pass away", meaning: "to die (polite)", example: "My grandfather passed away last year." },
  { term: "phase out", meaning: "to gradually stop using something", example: "Many countries plan to phase out petrol cars." },
  { term: "point out", meaning: "to draw attention to a fact", example: "Critics point out that the plan is expensive." },
  { term: "put off", meaning: "to postpone", example: "Don't put off your revision until the last week." },
  { term: "run out of", meaning: "to have no more of something", example: "We ran out of time before the last question." },
  { term: "set up", meaning: "to establish an organisation or business", example: "She set up her own company at 25." },
  { term: "take up", meaning: "to start a new hobby or activity", example: "I took up yoga to reduce stress." },
  { term: "turn down", meaning: "to refuse an offer", example: "He turned down a job abroad to stay near his family." },
  { term: "account for", meaning: "to form a particular amount of something", example: "Housing accounted for 34% of spending.", note: "Very useful in Task 1" },
  { term: "level off", meaning: "to stop rising or falling and stay the same", example: "Sales rose until 2015 and then levelled off.", note: "Task 1 trend language" },
  { term: "pick up", meaning: "to improve or recover", example: "Tourism picked up after 2021.", note: "Task 1 trend language" },
  { term: "die out", meaning: "to disappear completely", example: "Many local languages are dying out." },
  { term: "catch up on", meaning: "to do something you did not have time for earlier", example: "I use weekends to catch up on sleep." },
  { term: "look up to", meaning: "to admire and respect", example: "I've always looked up to my older sister." },
  { term: "stand out", meaning: "to be very noticeable or better than others", example: "Her essay stood out because of its clear argument." },
  { term: "work out", meaning: "to exercise; or to calculate", example: "I work out at the gym three times a week." },
  { term: "fall behind", meaning: "to fail to keep up with others", example: "Children who miss school often fall behind." },
  { term: "get over", meaning: "to recover from an illness or a bad experience", example: "It took weeks to get over the flu." },
  { term: "hand in", meaning: "to give work to a teacher or official", example: "Essays must be handed in by Friday." },
  { term: "take on", meaning: "to accept work or responsibility", example: "I took on too many projects last term." },
  { term: "rely on", meaning: "to depend on", example: "Many people rely on public transport." },
  { term: "settle down", meaning: "to start living a quieter, stable life", example: "My parents want me to settle down near home." },
  { term: "show off", meaning: "to try to impress people", example: "He bought an expensive car to show off." },
  { term: "think over", meaning: "to consider something carefully", example: "I'll think over your offer and reply tomorrow." },
];

